/**
 * Halloween — example seasonal content pack.
 *
 * Shows everything a pack can do: items built with the same helpers as the built-in library,
 * pack materials using a built-in pattern, a pack-made procedural pattern ("pumpkin-ribs") and
 * bitmap textures embedded at the end of this file (mossy stone, candy stripes), plus items that
 * glow. Delete this file and the items disappear from the library; projects that used them keep
 * a placeholder until the pack is back.
 */
import {
  blobCluster,
  clamp,
  cyl,
  defineItem,
  definePack,
  discZ,
  lathe,
  line,
  matSlot,
  pot,
  range,
  rng,
  rod,
  rodPath,
  sphere,
  span,
  torus,
  vcyl,
  type Part,
  type V2,
  type V3,
} from '@/packs/kit';

// Embedded seamless bitmaps (256 px mossy stone, 128 px candy stripes) made for this pack.
const MOSSY_STONE_PNG =
  'data:image/png;base64,';
const CANDY_STRIPES_PNG =
  'data:image/png;base64,';

/** A flat shape facing the front (+z): `pts` are [x, y] in metres, `t` thick from depth z. */
function facePlate(slot: string, pts: V2[], z: number, t: number): Part {
  const ys = pts.map((p) => p[1]);
  const mid = (Math.min(...ys) + Math.max(...ys)) / 2;
  const xs = pts.map((p) => p[0]);
  const cx = (Math.min(...xs) + Math.max(...xs)) / 2;
  // Prism outline lies in X/Z and extrudes along Y; rotating +90° about X turns it to face +z.
  return {
    shape: 'prism',
    outline: pts.map(([x, y]) => [x - cx, -(y - mid)] as V2),
    height: t,
    position: [cx, mid, z],
    rotation: [Math.PI / 2, 0, 0],
    slot,
    plan: false,
  };
}

/** Ribbed pumpkin body: lobes around the vertical axis, centred at (x, z), base at y0. */
function pumpkin(slot: string, x: number, z: number, y0: number, w: number, d: number, h: number, lobes = 8): Part[] {
  const parts: Part[] = [];
  // Pumpkins stay round: sized by the smaller footprint side.
  const s = Math.min(w, d);
  const r0 = s * 0.2;
  for (const k of range(lobes)) {
    const a = (k / lobes) * Math.PI * 2;
    parts.push(
      sphere(slot, [x + Math.cos(a) * r0, y0 + h * 0.5, z + Math.sin(a) * r0], 0.5, {
        scale: [s * 0.56, h, s * 0.36],
        rotation: [0, -a, 0],
        plan: k === 0,
      }),
    );
  }
  return parts;
}

const lantern = defineItem({
  id: 'jack-o-lantern',
  name: "Jack-o'-lantern",
  category: 'decor',
  type: 'decor',
  group: 'Candles & tabletop',
  tags: ['pumpkin', 'halloween', 'lantern', 'carved', 'candle', 'spooky'],
  defaultSize: { w: 0.36, d: 0.34, h: 0.36 },
  minSize: { w: 0.2, d: 0.2, h: 0.2 },
  maxSize: { w: 0.8, d: 0.8, h: 0.8 },
  slots: [
    matSlot('skin', 'Pumpkin skin', 'pumpkin-orange'),
    matSlot('stem', 'Stem', 'pumpkin-stem'),
    matSlot('light', 'Candle glow', 'carved-glow'),
  ],
  light: { color: '#ff9a3c', intensity: 0.9, distance: 2.4, y: 0.14 },
  build: ({ w, d, h }) => {
    const bodyH = h * 0.86;
    const zf = d * 0.43;
    const t = 0.012;
    const s = Math.min(w, bodyH);
    const y = (f: number) => bodyH * f;
    return [
      ...pumpkin('skin', 0, 0, 0, w * 0.98, d * 0.98, bodyH),
      // Stem with a little curl.
      lathe('stem', [0, bodyH * 0.9, 0], [
        [0, 0],
        [s * 0.07, 0],
        [s * 0.05, (h - bodyH * 0.9) * 0.6],
        [s * 0.035, h - bodyH * 0.9],
        [0, h - bodyH * 0.9],
      ]),
      // Carved face glowing from the candle inside.
      facePlate('light', [[-s * 0.3, y(0.58)], [-s * 0.1, y(0.58)], [-s * 0.2, y(0.74)]], zf, t),
      facePlate('light', [[s * 0.1, y(0.58)], [s * 0.3, y(0.58)], [s * 0.2, y(0.74)]], zf, t),
      facePlate('light', [[-s * 0.05, y(0.48)], [s * 0.05, y(0.48)], [0, y(0.56)]], zf, t),
      facePlate(
        'light',
        [
          [-s * 0.34, y(0.36)],
          [-s * 0.2, y(0.26)],
          [-s * 0.08, y(0.31)],
          [0, y(0.24)],
          [s * 0.08, y(0.31)],
          [s * 0.2, y(0.26)],
          [s * 0.34, y(0.36)],
          [s * 0.12, y(0.4)],
          [0, y(0.35)],
          [-s * 0.12, y(0.4)],
        ],
        zf,
        t,
      ),
    ];
  },
  planDetail: ({ w, d }) => [line([-w * 0.2, d * 0.3], [w * 0.2, d * 0.3])],
});

const pumpkinTrio = defineItem({
  id: 'pumpkin-trio',
  name: 'Pumpkin trio',
  category: 'decor',
  type: 'decor',
  group: 'Ornaments',
  tags: ['pumpkin', 'gourd', 'halloween', 'autumn', 'harvest'],
  defaultSize: { w: 0.7, d: 0.45, h: 0.34 },
  minSize: { w: 0.4, d: 0.25, h: 0.2 },
  maxSize: { w: 1.4, d: 0.9, h: 0.7 },
  slots: [
    matSlot('skin', 'Orange pumpkins', 'pumpkin-orange'),
    matSlot('pale', 'Pale pumpkin', 'pumpkin-pale'),
    matSlot('stem', 'Stems', 'pumpkin-stem'),
  ],
  build: ({ w, d, h }) => {
    const parts: Part[] = [];
    const specs: [number, number, number, string][] = [
      // [x centre (fraction of w), width (fraction of w), height (fraction of h), slot]
      [-0.25, 0.48, 0.92, 'skin'],
      [0.18, 0.4, 0.62, 'pale'],
      [0.38, 0.22, 0.4, 'skin'],
    ];
    for (const [fx, fw, fh, slot] of specs) {
      const pw = Math.min(w * fw, d * 0.98);
      const ph = h * fh * 0.85;
      const x = clamp(w * fx, -w / 2 + pw / 2, w / 2 - pw / 2);
      parts.push(...pumpkin(slot, x, 0, 0, pw, pw, ph, 7));
      parts.push(vcyl('stem', x, 0, ph * 0.88, Math.min(h, ph + h * fh * 0.15), pw * 0.05, { rTop: pw * 0.03, plan: false }));
    }
    return parts;
  },
});

const cauldron = defineItem({
  id: 'witch-cauldron',
  name: "Witch's cauldron",
  category: 'decor',
  type: 'decor',
  group: 'Ornaments',
  tags: ['cauldron', 'potion', 'witch', 'halloween', 'pot', 'glow'],
  defaultSize: { w: 0.62, d: 0.62, h: 0.56 },
  minSize: { w: 0.35, d: 0.35, h: 0.3 },
  maxSize: { w: 1.2, d: 1.2, h: 1.0 },
  slots: [
    matSlot('iron', 'Cast iron', 'cauldron-iron'),
    matSlot('light', 'Potion', 'potion-glow'),
  ],
  light: { color: '#59ff4a', intensity: 0.7, distance: 2.2, y: 0.45 },
  build: ({ w, d, h }) => {
    const r = Math.min(w, d) / 2;
    const legH = h * 0.14;
    const bodyH = h - legH;
    const rim = r * 0.08;
    const potionY = legH + bodyH * 0.8;
    const rand = rng(31);
    const parts: Part[] = [
      lathe('iron', [0, legH, 0], [
        [0, 0],
        [r * 0.55, 0],
        [r * 0.88, bodyH * 0.18],
        [r - rim, bodyH * 0.5],
        [r * 0.86, bodyH * 0.84],
        [r * 0.78, bodyH - rim],
      ], { segments: 32 }),
      torus('iron', [0, h - rim, 0], r * 0.8, rim * 0.9, { rotation: [Math.PI / 2, 0, 0], plan: false }),
      cyl('light', [0, potionY, 0], r * 0.76, 0.01, { segments: 32, plan: false }),
      // Rising bubbles.
      ...range(7).map((i) => {
        const a = rand() * Math.PI * 2;
        const rr = r * 0.55 * Math.sqrt(rand());
        const br = r * (0.04 + rand() * 0.06);
        return sphere('light', [Math.cos(a) * rr, Math.min(h - br, potionY + br * (0.4 + i * 0.25)), Math.sin(a) * rr], br, { plan: false });
      }),
      // Hanging handle loops.
      torus('iron', [-r * 0.84, h - rim * 3, 0], rim * 1.6, rim * 0.35, { rotation: [0, Math.PI / 2, 0], plan: false }),
      torus('iron', [r * 0.84, h - rim * 3, 0], rim * 1.6, rim * 0.35, { rotation: [0, Math.PI / 2, 0], plan: false }),
    ];
    // Three stubby feet.
    for (const k of range(3)) {
      const a = Math.PI / 2 + (k * Math.PI * 2) / 3;
      parts.push(vcyl('iron', Math.cos(a) * r * 0.45, Math.sin(a) * r * 0.45, 0, legH + 0.02, r * 0.08, { rTop: r * 0.11, plan: false }));
    }
    return parts;
  },
});

const gravestone = defineItem({
  id: 'gravestone',
  name: 'Gravestone',
  category: 'outdoor',
  type: 'decor',
  group: 'Ornaments',
  tags: ['tombstone', 'grave', 'rip', 'halloween', 'cemetery', 'stone'],
  defaultSize: { w: 0.5, d: 0.2, h: 0.75 },
  minSize: { w: 0.3, d: 0.12, h: 0.4 },
  maxSize: { w: 1.0, d: 0.4, h: 1.4 },
  slots: [
    matSlot('stone', 'Stone', 'mossy-stone'),
    matSlot('carving', 'Carving', 'stone-slate'),
  ],
  build: ({ w, d, h }) => {
    const baseH = Math.min(0.08, h * 0.12);
    const t = d * 0.55;
    const r = Math.min(w * 0.42, (h - baseH) * 0.45);
    const slabTop = h - r;
    const zf = t / 2;
    const cy = baseH + (slabTop - baseH) * 0.55;
    return [
      span('stone', [-w / 2, w / 2], [0, baseH], [-d / 2, d / 2], { bevel: 0.01 }),
      span('stone', [-r, r], [baseH, slabTop], [-t / 2, t / 2], { bevel: 0.008 }),
      discZ('stone', [0, slabTop, 0], r, t, { segments: 32, plan: false }),
      // Raised cross and an "RIP" plaque.
      span('carving', [-r * 0.06, r * 0.06], [slabTop - r * 0.15, slabTop + r * 0.55], [zf, zf + 0.012], { plan: false }),
      span('carving', [-r * 0.32, r * 0.32], [slabTop + r * 0.18, slabTop + r * 0.3], [zf, zf + 0.012], { plan: false }),
      span('carving', [-r * 0.6, r * 0.6], [cy - r * 0.22, cy + r * 0.12], [zf, zf + 0.008], { bevel: 0.003, plan: false }),
    ];
  },
});

const ghost = defineItem({
  id: 'sheet-ghost',
  name: 'Friendly sheet ghost',
  category: 'decor',
  type: 'decor',
  group: 'Ornaments',
  tags: ['ghost', 'boo', 'halloween', 'spooky', 'figure'],
  defaultSize: { w: 0.5, d: 0.45, h: 0.9 },
  minSize: { w: 0.25, d: 0.22, h: 0.4 },
  maxSize: { w: 1.0, d: 0.9, h: 1.8 },
  slots: [
    matSlot('sheet', 'Sheet', 'ghost-sheet'),
    matSlot('eyes', 'Eyes', 'solid-black'),
  ],
  build: ({ w, d, h }) => {
    const r = Math.min(w, d) / 2;
    const headR = Math.min(r * 0.62, h * 0.28);
    const headY = h - headR;
    const hem = range(9).map((i) => {
      const a = (i / 9) * Math.PI * 2;
      return sphere('sheet', [Math.cos(a) * r * 0.86, r * 0.12, Math.sin(a) * r * 0.86 * (d / w)], r * 0.13, { plan: false });
    });
    return [
      lathe('sheet', [0, r * 0.05, 0], [
        [r * 0.98, 0],
        [r * 0.9, (headY - r * 0.05) * 0.35],
        [r * 0.72, (headY - r * 0.05) * 0.75],
        [headR * 0.9, headY - r * 0.05],
        [0, headY - r * 0.05],
      ], { segments: 32, scale: [1, 1, d / w] }),
      sphere('sheet', [0, headY, 0], headR, { scale: [1, 1, d / w] }),
      ...hem,
      sphere('eyes', [-headR * 0.36, headY + headR * 0.12, headR * 0.86 * (d / w)], headR * 0.16, { scale: [1, 1.5, 0.5], plan: false }),
      sphere('eyes', [headR * 0.36, headY + headR * 0.12, headR * 0.86 * (d / w)], headR * 0.16, { scale: [1, 1.5, 0.5], plan: false }),
      sphere('eyes', [0, headY - headR * 0.32, headR * 0.86 * (d / w)], headR * 0.13, { scale: [1, 1.3, 0.5], plan: false }),
    ];
  },
});

const candelabra = defineItem({
  id: 'haunted-candelabra',
  name: 'Haunted candelabra',
  category: 'decor',
  type: 'decor',
  group: 'Candles & tabletop',
  tags: ['candelabra', 'candles', 'gothic', 'halloween', 'candle holder'],
  defaultSize: { w: 0.42, d: 0.14, h: 0.55 },
  minSize: { w: 0.25, d: 0.1, h: 0.35 },
  maxSize: { w: 0.8, d: 0.3, h: 1.0 },
  slots: [
    matSlot('metal', 'Tarnished metal', 'cauldron-iron'),
    matSlot('wax', 'Candles', 'candle-wax'),
    matSlot('light', 'Flames', 'light-candle'),
  ],
  light: { color: '#ffb35c', intensity: 0.6, distance: 2.5, y: 0.5 },
  build: ({ w, d, h }) => {
    const cupY = h * 0.55;
    const candleH = h - cupY - 0.06;
    const arm = w / 2 - 0.035;
    const parts: Part[] = [
      lathe('metal', [0, 0, 0], [
        [0, 0],
        [d * 0.48, 0],
        [d * 0.45, 0.015],
        [d * 0.2, 0.04],
        [0.012, 0.07],
        [0.012, cupY],
        [0, cupY],
      ]),
      sphere('metal', [0, cupY * 0.45, 0], 0.022, { plan: false }),
      ...rodPath('metal', [[-arm, cupY, 0], [-arm * 0.7, cupY - h * 0.12, 0], [0, cupY - h * 0.16, 0], [arm * 0.7, cupY - h * 0.12, 0], [arm, cupY, 0]], 0.007),
    ];
    for (const x of [-arm, 0, arm]) {
      const ch = x === 0 ? candleH : candleH * 0.85;
      parts.push(cyl('metal', [x, cupY + 0.008, 0], 0.03, 0.016, { rTop: 0.034, plan: false }));
      parts.push(vcyl('wax', x, 0, cupY + 0.016, cupY + 0.016 + ch, 0.016, { plan: false }));
      // Wax drips.
      parts.push(sphere('wax', [x + 0.012, cupY + 0.016 + ch * 0.75, 0.008], 0.006, { scale: [1, 2.5, 1], plan: false }));
      parts.push(sphere('light', [x, cupY + 0.016 + ch + 0.018, 0], 0.009, { scale: [1, 2, 1], plan: false }));
    }
    return parts;
  },
});

const spiderWeb = defineItem({
  id: 'spider-web',
  name: 'Spider web with spider',
  category: 'decor',
  type: 'decor',
  group: 'Wall art',
  tags: ['cobweb', 'spider', 'web', 'halloween', 'spooky'],
  mount: 'wall',
  defaultElevation: 1.5,
  defaultSize: { w: 0.8, d: 0.05, h: 0.8 },
  minSize: { w: 0.3, d: 0.03, h: 0.3 },
  maxSize: { w: 2.0, d: 0.1, h: 2.0 },
  slots: [
    matSlot('web', 'Web', 'cobweb'),
    matSlot('spider', 'Spider', 'solid-black'),
  ],
  build: ({ w, d, h }) => {
    const cx = 0;
    const cy = h / 2;
    const z = -d / 2 + 0.01;
    const rx = w / 2 - 0.01;
    const ry = h / 2 - 0.01;
    const spokes = 10;
    const pt = (k: number, f: number): V3 => {
      const a = (k / spokes) * Math.PI * 2;
      return [cx + Math.cos(a) * rx * f, cy + Math.sin(a) * ry * f, z];
    };
    const parts: Part[] = [span('web', [-0.01, 0.01], [cy - 0.01, cy + 0.01], [-d / 2, -d / 2 + 0.02])];
    for (const k of range(spokes)) parts.push(rod('web', pt(k, 0), pt(k, 1), 0.0016, { plan: false }));
    for (const f of [0.25, 0.45, 0.65, 0.85]) {
      for (const k of range(spokes)) parts.push(rod('web', pt(k, f), pt(k + 1, f * 0.97), 0.0012, { plan: false }));
    }
    // Spider hanging below the centre.
    const sy = cy - ry * 0.35;
    const sz = z + 0.02;
    const sr = Math.min(Math.min(w, h) * 0.035, 0.05, d * 0.8);
    parts.push(rod('web', [cx, cy, z], [cx, sy, sz], 0.001, { plan: false }));
    parts.push(sphere('spider', [cx, sy, sz], sr, { scale: [1, 1.2, 0.8], plan: false }));
    parts.push(sphere('spider', [cx, sy + sr * 1.4, sz], sr * 0.6, { plan: false }));
    for (const side of [-1, 1]) {
      for (const k of range(4)) {
        const yy = sy + sr * (0.6 - k * 0.45);
        parts.push(...rodPath('spider', [[cx, yy, sz], [cx + side * sr * 1.8, yy + sr * 0.6, sz], [cx + side * sr * 2.6, yy - sr * 0.5, sz]], sr * 0.09));
      }
    }
    return parts;
  },
});

const batGarland = defineItem({
  id: 'bat-garland',
  name: 'Bat garland',
  category: 'decor',
  type: 'decor',
  group: 'Wall art',
  tags: ['bats', 'garland', 'bunting', 'halloween', 'party'],
  mount: 'wall',
  defaultElevation: 1.8,
  defaultSize: { w: 1.6, d: 0.04, h: 0.3 },
  minSize: { w: 0.6, d: 0.03, h: 0.15 },
  maxSize: { w: 4.0, d: 0.1, h: 0.6 },
  slots: [
    matSlot('bats', 'Bats', 'black-velvet'),
    matSlot('string', 'String', 'candle-wax'),
  ],
  build: ({ w, d, h }) => {
    const n = clamp(Math.round(w / 0.28), 3, 14);
    const sag = h * 0.45;
    const z = -d / 2 + 0.01;
    const yAt = (x: number) => h - 0.02 - sag * (1 - ((2 * x) / w) ** 2);
    const pts: V3[] = range(13).map((i) => {
      const x = -w / 2 + 0.01 + ((w - 0.02) * i) / 12;
      return [x, yAt(x), z];
    });
    const parts: Part[] = [...rodPath('string', pts, 0.0015), span('string', [-w / 2, -w / 2 + 0.02], [h - 0.03, h], [-d / 2, -d / 2 + 0.01])];
    const bw = Math.min(0.2, (w / n) * 0.8);
    const bh = Math.min(h * 0.4, bw * 0.45);
    for (const k of range(n)) {
      const x = -w / 2 + ((k + 0.5) * w) / n;
      const y = clamp(yAt(x) - bh * 0.55, bh / 2, h - bh / 2);
      const s = bw / 2;
      parts.push(
        facePlate(
          'bats',
          [
            [-s, y + bh * 0.3],
            [-s * 0.7, y - bh * 0.1],
            [-s * 0.45, y + bh * 0.05],
            [-s * 0.2, y - bh * 0.4],
            [0, y - bh * 0.1],
            [s * 0.2, y - bh * 0.4],
            [s * 0.45, y + bh * 0.05],
            [s * 0.7, y - bh * 0.1],
            [s, y + bh * 0.3],
            [s * 0.15, y + bh * 0.2],
            [0, y + bh * 0.5],
            [-s * 0.15, y + bh * 0.2],
          ].map(([px, py]) => [x + px, py] as V2),
          z + 0.002,
          0.004,
        ),
      );
    }
    return parts;
  },
});

